def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "~": 3, "^": 4}

    def apply():
        op = operators.pop()

        if op == "~":
            values.append(-values.pop())
            return True

        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "^":
            if b < 0:
                return False
            values.append(pow(a, b))
        else:
            if b == 0:
                return False
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            values.append(quotient if op == "/" else a - b * quotient)

        return True

    i = 0
    n = len(expr)
    expect_operand = True

    while i < n:
        ch = expr[i]

        if ch == " ":
            i += 1
        elif "0" <= ch <= "9":
            value = 0
            while i < n and "0" <= expr[i] <= "9":
                value = value * 10 + ord(expr[i]) - ord("0")
                i += 1
            values.append(value)
            expect_operand = False
        elif ch == "(":
            operators.append(ch)
            i += 1
            expect_operand = True
        elif ch == ")":
            while operators[-1] != "(":
                if not apply():
                    return "error"
            operators.pop()
            i += 1
            expect_operand = False
        elif ch == "-" and expect_operand:
            operators.append("~")
            i += 1
        else:
            while (
                operators
                and operators[-1] != "("
                and (
                    precedence[operators[-1]] > precedence[ch]
                    or (precedence[operators[-1]] == precedence[ch] and ch != "^")
                )
            ):
                if not apply():
                    return "error"
            operators.append(ch)
            i += 1
            expect_operand = True

    while operators:
        if not apply():
            return "error"

    return values[0]
